	if state1After.Phase != session.PhaseEnded {
		t.Errorf("Session 1 phase changed! Expected ENDED, got %s", state1After.Phase)
	}

	// ========================================
	// Phase 7: Verify session 2 WAS condensed
	// ========================================
	t.Log("Phase 7: Verifying session 2 WAS condensed")

