	env := NewTestEnv(t)
	defer env.Cleanup()

	// ========================================
	// Setup
	// ========================================
	env.InitRepo()
	env.WriteFile("README.md", "# Test Repository")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.GitCheckoutNewBranch("feature/stale-active-test")
	env.InitEntire(strategy.StrategyNameManualCommit)

	// ========================================
	// Phase 1: Session 1 creates file, then "crashes" (stays ACTIVE)
	// IMPORTANT: We do NOT call SimulateStop - this simulates an agent that was
	// killed mid-turn before the Stop hook could fire. This means:
	// - CheckpointTranscriptStart stays at 0
	// - hasNew will be TRUE (transcript lines > 0)
	// - The bug would cause this session to be condensed into ANY commit
	// ========================================
	t.Log("Phase 1: Session 1 creates file1.txt, agent is killed mid-turn (no Stop hook)")

	session1 := env.NewSession()
	if err := env.SimulateUserPromptSubmit(session1.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit for session1 failed: %v", err)
	}

	// Create file and transcript, but DO NOT call SimulateStop
	// This simulates the agent being killed before Stop hook fired
	env.WriteFile("file1.txt", "content from session 1")
	session1.CreateTranscript(
		"Create file1",
		[]FileChange{{Path: "file1.txt", Content: "content from session 1"}},
	)
	// NO SimulateStop here! Agent was "killed"

	// Verify session1 is still ACTIVE (no Stop hook fired)
	state1, err := env.GetSessionState(session1.ID)
	if err != nil {
		t.Fatalf("GetSessionState for session1 failed: %v", err)
	}
	if state1.Phase != session.PhaseActive {
		t.Fatalf("Expected session1 to be ACTIVE (no Stop fired), got %s", state1.Phase)
	}

	// Record state for comparison
	session1StepCount := state1.StepCount
	t.Logf("Session1 (stale ACTIVE, no Stop) BaseCommit: %s, StepCount: %d, CheckpointTranscriptStart: %d",
		state1.BaseCommit[:7], session1StepCount, state1.CheckpointTranscriptStart)

